#include <iomanip>
#include <iostream>
#include <sstream>
#include <string>

std::string formatPriceTag(const std::string& name, double price) {
    std::ostringstream out;
    out << name << ": $" << std::fixed << std::setprecision(2) << price;
    return out.str();
}

int main() {
    std::string name;
    double price;
    std::cin >> name >> price;
    std::cout << formatPriceTag(name, price) << "\n";
    return 0;
}

